variables.body:
if (this.companyMap && this.companyMap.length > 0 && !this.companyId) {
    this.companyId = this.companyMap[0].value;
    this.companyName = this.companyMap[0].label;
}

if ((this.menuItems[0].label === "Select a Company" || this.menuItems[0].label === "Create a Company") && !this.companyId) return;

if (this.companyMap.length === 0 && this.menuItems[0].label !== "Create a Company") {
    this.menuItems.unshift(
        {
            label: "Create a Company",
            evaluateLabel: false,
            onClick: "function",
            function: () => {
                const targetStateName = 'global_management';
                const stateParams = {
                    createFirstCompany: 'true'
                };

                this.$state.go(targetStateName, stateParams)
                    .then(() => {
                    })
                    .catch((error) => {
                        console.error(`Error transitioning to state '${targetStateName}':`, error);
                    });
            },
            icon: {
                name: "building",
                style: "solid",
                type: "font-icon",
                position: "left"
            }
        }
    );
    return;
}

if (this.companyMap.length === 1) {
    const company = this.companyMap[0]
    this.companyId = company.value;
    this.companyName = company.label;
    if (this.menuItems[0].menuItems) this.menuItems.shift();
    this.menuItems.unshift(
        {
            label: this.companyName || "Select a Company",
            evaluateLabel: true,
            icon: {
                name: "building",
                style: "solid",
                type: "font-icon",
                position: "left"
            }
        });
    if (this.menuItems[1].label !== "Dashboard") this.menuItems.shift();
    return;
}

if (this.menuItems[0].label === "Dashboard") this.menuItems.unshift(
    {
        label: this.companyName || "Select a Company",
        evaluateLabel: true,
        menuItems: [],
        icon: {
            name: "building",
            style: "solid",
            type: "font-icon",
            position: "left"
        }
    });

else {
    this.menuItems[0].label = this.companyName;

    if (this.menuItems[0].menuItems.length === 0) {
        this.setCompanyMenuItems();
    }

    return;
}

this.setCompanyMenuItems();

try {
    const LABEL_SELECT_COMPANY = "Select a Company";
    const LABEL_CREATE_COMPANY = "Create a Company";

    // 1. Ensure this.menuItems is an array.
    if (!Array.isArray(this.menuItems)) {
        this.menuItems = [];
    }

    let primaryDropdown = this.menuItems[0];
    if (!Array.isArray(primaryDropdown.menuItems)) {
        primaryDropdown.menuItems = [];

        // Add the currently selected Company, if any
        const currentCompanyId = this.companyId;
        const currentCompanyName = this.companyName;

        if (currentCompanyId) {
            const currentCompanyItem = {
                label: currentCompanyName,
                evaluateLabel: true,
                value: currentCompanyId,
                onClick: "function",
                function: () => this.setCompany(currentCompanyItem, currentCompanyName)
            };

            primaryDropdown.menuItems.push(currentCompanyItem);
        }
    }

    // 2. Create the new Company menu item.
    const newCompanyItem = {
        label: companyName,
        evaluateLabel: true,
        value: companyId,
        onClick: "function",
        function: () => this.setCompany(companyId, companyName)
    };

    // 3. Add the new item to the sub-menu.
    primaryDropdown.menuItems.push(newCompanyItem);

    // 4. Change the dropdown label if first Company item
    if (primaryDropdown.label === LABEL_CREATE_COMPANY) primaryDropdown.label = LABEL_SELECT_COMPANY;

} catch (error) {
    console.error(`Error in addCompanyMenuItem while adding Company '${companyName}' (ID: '${companyId}'):`, error);
    throw error;
}

try {
    // 1. Safely access the primary dropdown and its sub-menu items.
    const primaryDropdown = (this.menuItems && Array.isArray(this.menuItems) && this.menuItems.length > 0)
        ? this.menuItems[0]
        : null;

    const subMenuItems = (primaryDropdown && primaryDropdown.menuItems && Array.isArray(primaryDropdown.menuItems))
        ? primaryDropdown.menuItems
        : null;

    if (subMenuItems) {
        // 2. Find the specific item to update in the sub-menu.
        //    It's good practice to check if `item` and `item.value` exist.
        const itemToUpdate = subMenuItems.find(item => item && item.value === companyId);

        // 3. If the item is found, update its properties.
        if (itemToUpdate) {
            itemToUpdate.label = newCompanyName;
            itemToUpdate.function = () => this.setCompany(companyId, newCompanyName);
        } else {
            // console.warn(`Menu item with companyId: ${companyId} not found in sub-menu. Cannot update item label/function.`);
        }
    } else {
        // console.warn("Sub-menu items list not found. Cannot update any menu item.");
    }

    // 4. If the company being updated is the currently selected/active company,
    //    update the global company name and potentially the primary dropdown's label.
    if (this.companyId === companyId) {
        this.companyName = newCompanyName;
        if (primaryDropdown) {
            primaryDropdown.label = newCompanyName;
        }
    }

} catch (error) {
    console.error(`Error in updateCompanyMenuItem for companyId '${companyId}', newName '${newCompanyName}':`, error);
    throw error;
}

try {
    const LABEL_SELECT_COMPANY = "Select a Company";
    const LABEL_CREATE_COMPANY = "Create a Company";

    // Part 1: Remove the company from the sub-menu list
    const primaryDropdown = this.menuItems && this.menuItems.length > 0 ? this.menuItems[0] : null;

    if (primaryDropdown && primaryDropdown.menuItems && Array.isArray(primaryDropdown.menuItems)) {
        const subMenuItems = primaryDropdown.menuItems;
        const itemIndex = subMenuItems.findIndex(item => item && item.value === companyIdToDelete);

        if (itemIndex > -1) {
            subMenuItems.splice(itemIndex, 1);
        }
    }

    // Part 2: Update the currently selected company if it was the one deleted.
    if (this.companyId === companyIdToDelete) {
        this.menuItems.shift();
        this.companyId = undefined;
    }

    // Part 3: Change the primaryDropdown label if it's Select a Company and there are no Companies
    if (primaryDropdown.label === LABEL_SELECT_COMPANY && this.companyMap.length === 0) {
        primaryDropdown.label = LABEL_CREATE_COMPANY;
    }

} catch (error) {
    console.error(`Error in deleteCompanyMenuItem while processing companyId '${companyIdToDelete}':`, error);
    throw error; 
}

this.companyMap.forEach(company =>
    this.menuItems[0].menuItems.push(
        {
            label: company.label,
            evaluateLabel: true,
            value: company.value,
            onClick: "function",
            function: () => this.setCompany(company.value, company.label)
        })
);
